  assert.deepEqual(spiral([[]]), []);
});

test('single row', () => {
  assert.deepEqual(spiral([[1, 2, 3, 4]]), [1, 2, 3, 4]);
});

test('single column', () => {
  assert.deepEqual(spiral([[1], [2], [3]]), [1, 2, 3]);
});

test('validation errors', () => {
  assert.throws(() => spiral('not an array'), TypeError);
  assert.throws(() => spiral([[1, 2], [3]]), TypeError);
